using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "LightningCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/LightningCustomDescription", order = 0)]
public class LightningCustomDescription : CustomBattleActionDescription
{
	[SerializeField]
	private PurifyCorruptCustomDescription purifyCorruptCustomDescription;

	[SerializeField]
	private bool purify;

	[SerializeField]
	private bool checkForLatinLanguage;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		LightningAction lightningAction = battleAction as LightningAction;
		string text = (purify ? "Purify_D" : "Corrupt_D");
		if (checkForLatinLanguage && LanguagesIndexes.IsCurrentLanguageLatinLanguage())
		{
			text += "FutureLatinLanguages";
		}
		string localizedString = base.localizationManager.GetLocalizedString(text);
		localizedString = Smart.Format(purifyCorruptCustomDescription.GetTargetCorruptPurifyLocalized(battleAction).RemoveLast(), Smart.Format(localizedString, lightningAction.CorruptPurifyAmountWithModifier));
		string text2 = "";
		if (battleAction is SharkRushAction)
		{
			text2 = "\n" + base.localizationManager.GetLocalizedCorruptionNotIncreasedByCorruptionModifier();
		}
		return base.localizationManager.GetLocalizedXTimesFormatted(localizedString, GetAmountWithoutEquation(amountModified)) + text2;
	}
}
